function sortMarkStatic(active: boolean, direction: SortDirection) {
  return active ? (direction === "asc" ? "â†‘" : "â†“") : "â†•";
}

function RankingBlock({
  metric,
  title,
  subtitle,
  rows,
  plan,
  tone,
  showTrend = false,
  countMode = false,
  lowerIsBetter = false,
  gapMode = false,
  emptyText = "ÐÐµÑ‚ Ð´Ð°Ð½Ð½Ñ‹Ñ… Ð´Ð»Ñ ÑÑ€Ð°Ð²Ð½ÐµÐ½Ð¸Ñ Ð¿ÐµÑ€Ð¸Ð¾Ð´Ð¾Ð²",
}: {
  metric?: string;
  title: string;
  subtitle: string;
  rows: MoRow[];
  plan: number;
  tone: string;
  showTrend?: boolean;
  countMode?: boolean;
  lowerIsBetter?: boolean;
  gapMode?: boolean;
  emptyText?: string;
}) {
  const max = Math.max(...rows.map((r) => r.fact), 1);
  return (
    <article
      className={`rankingBlock ${tone} ${showTrend ? "changeBlock" : ""} ${gapMode ? "gapRanking" : ""}`}
    >
      <div className="rankingTitle">
        <div>
          <h3>{title}</h3>
          <span>{subtitle}</span>
        </div>
        <b>{rows.length}</b>
      </div>
      <div className="rankingRows">
        {rows.length === 0 ? (
          <p className="emptyRanking">{emptyText}</p>
        ) : (
          rows.map((r, i) => {
            const displayName = metric
              ? reportMoName(metric, r.name)
              : displayMoName(r.name, r.oid);
            const target =
              r.volume === null || r.volume === undefined
                ? null
                : Math.ceil((r.volume * plan) / 100);
            const gap =
              target === null
                ? null
                : Math.max(0, target - Number(r.count ?? 0));
            return (
              <div key={r.name}>
                <span className="miniRank">{i + 1}</span>
                <p title={displayName}>
                  {displayName}
                  {gapMode && (
                    <small>
                      {format(r.count ?? 0, 0)} Ð¸Ð· {format(r.volume ?? 0, 0)}
                    </small>
                  )}
                </p>
                {gapMode ? (
                  <b className={r.fact >= plan ? "green" : "badText"}>
                    <span>{format(r.fact, 2)}%</span>
                    {gap !== null && gap > 0 && (
                      <small>Ð½Ðµ Ñ…Ð²Ð°Ñ‚Ð°ÐµÑ‚ {format(gap, 0)}</small>
                    )}
                  </b>
                ) : showTrend ? (
                  <b
                    className={
                      !countMode && r.fact < plan ? "badText" : "green"
                    }
                  >
                    {format(r.fact, countMode ? 0 : 2)}
                    {countMode ? "" : "%"}
                  </b>
                ) : (
                  <div className="miniBar">
                    <i
                      style={{
                        width: `${Math.min((r.fact / (countMode ? max : Math.max(plan, 1))) * 100, 100)}%`,
                      }}
                    />
                  </div>
                )}
                {!gapMode && (
                  <strong
                    className={
                      showTrend &&
                      r.trend !== null &&
                      (lowerIsBetter ? r.trend > 0 : r.trend < 0)
                        ? "badText"
                        : ""
                    }
                  >
                    {showTrend && r.trend !== null
                      ? `${r.trend > 0 ? "â†‘" : r.trend < 0 ? "â†“" : "â†’"} ${format(Math.abs(r.trend), countMode ? 0 : 2)}${countMode ? "" : " Ð¿.Ð¿."}`
                      : `${format(r.fact, countMode ? 0 : 2)}${countMode ? "" : "%"}`}
                  </strong>
                )}
              </div>
            );
          })
        )}
      </div>
    </article>
  );
}
